import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.Cdp8-jB6.js";const p=JSON.parse('{"title":"ADR-082 — Telemetry environment ladder (dev → staging → prod, isolated projects)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-082.md","filePath":"adr/ADR-082.md"}'),d={name:"adr/ADR-082.md"};function a(s,e,i,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-082-—-telemetry-environment-ladder-dev-→-staging-→-prod-isolated-projects" tabindex="-1">ADR-082 — Telemetry environment ladder (dev → staging → prod, isolated projects) <a class="header-anchor" href="#adr-082-—-telemetry-environment-ladder-dev-→-staging-→-prod-isolated-projects" aria-label="Permalink to &quot;ADR-082 — Telemetry environment ladder (dev → staging → prod, isolated projects)&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-07-24 Related ADRs · ADR-067 (Sentry/GlitchTip error tracking — extended here), ADR-081 (self-hosted Umami analytics — extended here), ADR-070 / ADR-071 (docs vs app deploy split, the <code>staging</code> workflow this retargets) Supersedes wording in · ADR-067 §&quot;Local-dev posture&quot; and ADR-081 §&quot;Why env-var-gated&quot; (both said <code>vite dev</code> is hard-silent — no longer true; see below)</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Two sibling ADRs already gate browser telemetry on env vars, not hostname: ADR-067 (Sentry SDK → self-hosted <strong>GlitchTip</strong>) and ADR-081 (self-hosted <strong>Umami</strong>). Both shipped with a binary posture: <strong>a deploy bakes the <code>PUBLIC_*</code> vars → telemetry is live; everything else (<code>vite dev</code>, <code>vite preview</code>, CI, forks) is silent.</strong></p><p>That binary posture had two gaps once the product went to production on <code>orrerylearn.com</code> (VPS + Cloudflare) while the <code>chipi.github.io/orrery</code> gh-pages mirror kept deploying:</p><ol><li><strong>The gh-pages deploy is not a &quot;preview&quot; — it is a real, publicly reachable environment.</strong> It was labelled <code>production</code> in its Sentry env tag and set no Umami at all, so its error traffic <strong>polluted the prod GlitchTip project</strong> and its usage was invisible. A shared prod dashboard that mixes two live environments cannot answer &quot;is this error happening to real users?&quot;</li><li><strong>Local <code>vite dev</code> was telemetry-blind.</strong> A crash or a UX dead-end an engineer hit while developing produced nothing — no error in any GlitchTip project, no event in any Umami site. The one environment where we iterate fastest was the one with no feedback loop.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Model telemetry as a three-rung environment ladder. Each rung reports to its own isolated GlitchTip project + Umami site, tagged by environment, so no rung&#39;s data ever contaminates another&#39;s.</strong></p><table tabindex="0"><thead><tr><th>Rung</th><th>Where</th><th>GlitchTip project</th><th>Umami site</th><th><code>environment</code> tag</th><th>How it&#39;s selected</th></tr></thead><tbody><tr><td><strong>prod</strong></td><td><code>orrerylearn.com</code> (VPS + CF)</td><td><strong>4</strong></td><td>prod site (<code>4a25d8da…</code>)</td><td><code>production</code></td><td><code>deploy-prod.yml</code> bakes <code>PUBLIC_SENTRY_DSN</code> + <code>PUBLIC_UMAMI_*</code> from the <code>prod</code> GH environment</td></tr><tr><td><strong>staging</strong></td><td><code>chipi.github.io/orrery</code> (gh-pages)</td><td><strong>6</strong></td><td>staging site (<code>6e7ddfce…</code>)</td><td><code>staging</code></td><td><code>staging.yml</code> bakes them from the new <code>staging</code> GH environment</td></tr><tr><td><strong>dev</strong></td><td>maintainer&#39;s laptop, <code>vite dev</code></td><td><strong>7</strong></td><td>dev site (<code>1d2f214c…</code>)</td><td><code>dev</code></td><td>fallback constants in <code>sentry.ts</code> / <code>analytics.ts</code>, reached only over the Tailscale <code>homelab</code> host</td></tr></tbody></table><p>Concretely:</p><ul><li><strong><code>preview.yml</code> → <code>staging.yml</code>.</strong> The gh-pages deploy is renamed and declares <code>environment: staging</code> (a new GH environment holding the staging-only DSN + Umami id), mirroring <code>deploy-prod.yml</code>&#39;s <code>environment: prod</code>. Its Sentry env tag is <code>staging</code>, not the old mislabeled <code>production</code>. (References updated in <code>release.yml</code>, <code>deploy-docs.yml</code>, <code>docker-e2e.yml</code>.)</li><li><strong>Dev rung.</strong> In <code>vite dev</code> with no deploy-injected <code>PUBLIC_*</code> override, <code>sentry.ts</code> falls back to <code>DEV_SENTRY_DSN</code> (GlitchTip project 7) and <code>analytics.ts</code> falls back to <code>DEV_UMAMI_HOST</code>/<code>DEV_UMAMI_WEBSITE_ID</code> (the dev Umami site). Both endpoints resolve <strong>only</strong> via the Tailscale MagicDNS host <code>homelab</code> (GlitchTip <code>:8090</code>, Umami <code>:3001</code>) — <strong>no fixed IP</strong>.</li><li><strong>Worktree tag.</strong> <code>vite.config.ts</code> injects the current git branch as the <code>__DEV_WORKTREE__</code> define; <code>sentry.ts</code> adds it as a <code>worktree</code> tag <strong>on dev events only</strong>, so errors from parallel local worktrees/agents stay distinguishable in the dev project. It is never attached to staging/prod events.</li></ul><h2 id="why-this-preserves-fork-silence-the-load-bearing-property" tabindex="-1">Why this preserves fork-silence (the load-bearing property) <a class="header-anchor" href="#why-this-preserves-fork-silence-the-load-bearing-property" aria-label="Permalink to &quot;Why this preserves fork-silence (the load-bearing property)&quot;">​</a></h2><p>The binary posture&#39;s one real guarantee — <strong>a stranger who clones the repo sends nothing</strong> — is kept, now <em>by construction</em> rather than by a <code>dev</code> hard-block:</p><ul><li><strong>Deploy rungs (prod/staging):</strong> the <code>PUBLIC_*</code> values live in GH environment secrets a fork doesn&#39;t have. A fork&#39;s build bakes empty → SDK/tracker no-op.</li><li><strong>Dev rung:</strong> the fallback DSN/host is the <strong>Tailscale-only</strong> name <code>homelab</code>. Only a device on <em>our</em> tailnet resolves it. On a stranger&#39;s machine <code>vite dev</code> resolves nothing, the transport fails, and no event leaves the browser. The DSN key + Umami id are public browser ids (they ship in the bundle by design — same as any Sentry DSN), so committing them leaks nothing.</li></ul><p>So the guarantee moved from &quot;dev is hard-blocked&quot; to &quot;dev&#39;s endpoint is unreachable off the tailnet.&quot; Same outcome for forks; a working feedback loop for the maintainer.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong><code>vite dev</code> is no longer silent for the maintainer.</strong> Any doc that says &quot;local dev is silent / dev sends nothing&quot; is now only true <em>for non-tailnet machines</em>. Updated: README §Privacy, <code>src/lib/analytics.ts</code> module JSDoc, <code>docs/guides/observability.md</code>, ADR-067 / ADR-081 (amendment pointers to here).</li><li><strong>New infra (homelab, owned by the infra repo):</strong> GlitchTip project 6 (<code>orrery-staging</code>) + 7 (<code>orrery-dev</code>); Umami sites <code>6e7ddfce…</code> (staging) + <code>1d2f214c…</code> (dev); the GH <code>staging</code> environment + its secrets.</li><li><strong><code>vite preview</code>, screenshot pipeline, e2e stay silent</strong> — they are not <code>dev</code> and carry no baked <code>PUBLIC_*</code>, so no rung resolves. The public prod dataset reflects real visitors only.</li><li><strong>Reading a dev error requires being on the tailnet.</strong> Acceptable — dev telemetry is a maintainer convenience, not a product surface.</li></ul><h2 id="not-covered-out-of-scope" tabindex="-1">Not covered / out of scope <a class="header-anchor" href="#not-covered-out-of-scope" aria-label="Permalink to &quot;Not covered / out of scope&quot;">​</a></h2><ul><li>Native mobile crash reporting (<code>@sentry/capacitor</code>, #428) is a separate feature on its own branch; it plugs into the same GlitchTip but is not part of this browser-ladder decision.</li><li>Log shipping (ADR-068 Grafana Agent / VictoriaLogs) is a server-side concern, not browser telemetry, and is untouched here.</li><li>The public-vhost hardening that hides the GlitchTip/Umami admin surfaces is the infra repo&#39;s responsibility (as in ADR-081).</li></ul>',19)])])}const m=o(d,[["render",a]]);export{p as __pageData,m as default};
